INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_042_M6_S1', 'adsorption equilibria', '1', 'adsorption equilibria: Relationships between the amount adsorbed on a solid surface and fluid-phase concentration or pressure at equilibrium. In Adsorption and Membrane Separation, the focus is on the analysis, design, implementation, interpretation, or evaluation of adsorption equilibria within Mass Transfer Operations, particularly where the Adsorption and Membrane Separation module establishes its technical context.', 'SSD_COURSE_042_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M6_S2', 'breakthrough', '2', 'breakthrough refers to the point at which a contaminant or solute begins to appear significantly in the outlet of an adsorption bed. In Adsorption and Membrane Separation, the focus is on the analysis, design, implementation, interpretation, or evaluation of breakthrough within Mass Transfer Operations, particularly where the Adsorption and Membrane Separation module establishes its technical context.', 'SSD_COURSE_042_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M6_S3', 'membrane transport', '3', 'membrane transport: Movement of species through a membrane driven by differences in chemical potential, pressure, concentration, or electric potential. In Adsorption and Membrane Separation, the focus is on the analysis, design, implementation, interpretation, or evaluation of membrane transport within Mass Transfer Operations, particularly where the Adsorption and Membrane Separation module establishes its technical context.', 'SSD_COURSE_042_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M6_S4', 'Membrane selectivity', '4', 'Membrane selectivity: Degree to which a membrane preferentially permeates one component relative to another, determined by differences in sorption and transport properties and expressed through appropriate selectivity metrics. In Adsorption and Membrane Separation, the focus is on curricular scope: Mass Transfer Operations; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_042_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M6_S5', 'Membrane permeability', '5', 'Membrane permeability: Permeability of a membrane to a specified component or species, governing the rate at which that component passes through the membrane under a specified driving force. In Adsorption and Membrane Separation, the focus is on curricular scope: Mass Transfer Operations; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_042_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M7_S1', 'column hydraulics', '1', 'column hydraulics: Flow behaviour in packed or tray columns, including pressure drop, loading, entrainment, and flooding. In Mass-Transfer Equipment Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of column hydraulics within Mass Transfer Operations, particularly where the Mass-Transfer Equipment Design module establishes its technical context.', 'SSD_COURSE_042_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M7_S2', 'flooding', '2', 'flooding: Excessive gas or liquid flow in a separation column that disrupts normal countercurrent operation. In Mass-Transfer Equipment Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of flooding within Mass Transfer Operations, particularly where the Mass-Transfer Equipment Design module establishes its technical context.', 'SSD_COURSE_042_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M7_S3', 'pressure drop', '3', 'pressure drop refers to the reduction in fluid pressure along equipment or piping caused by friction, fittings, elevation, or other flow resistance. In Mass-Transfer Equipment Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of pressure drop within Fluid Flow and Heat Transfer, particularly where the External Flow and Boundary Layers module establishes its technical context.', 'SSD_COURSE_042_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M7_S4', 'scale-up', '4', 'scale-up: Translation of process or equipment behaviour from a smaller reference scale to a larger scale while accounting for geometric, transport, kinetic, and operating constraints. In Mass-Transfer Equipment Design, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_042_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_042_M7_S5', 'process integration', '5', 'process integration: Coordinating separation and transport operations to reduce energy, material use, equipment demand, or operating cost. In Mass-Transfer Equipment Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of process integration within Mass Transfer Operations, particularly where the Mass-Transfer Equipment Design module establishes its technical context.', 'SSD_COURSE_042_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M1_S1', 'rate laws', '1', 'rate laws: rate laws in Chemical Reaction Engineering concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing rate laws. In Reaction Kinetics, the focus is on the analysis, design, implementation, interpretation, or evaluation of rate laws within Chemical Reaction Engineering, particularly where the Reaction Kinetics module establishes its technical context.', 'SSD_COURSE_043_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M1_S2', 'reaction order', '2', 'reaction order refers to the exponent describing how the rate of a reaction depends on the concentration of a reactant in a rate expression. In Reaction Kinetics, the focus is on the analysis, design, implementation, interpretation, or evaluation of reaction order within Chemical Reaction Engineering, particularly where the Reaction Kinetics module establishes its technical context.', 'SSD_COURSE_043_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M1_S3', 'Arrhenius equation', '3', 'Arrhenius equation refers to an equation relating a reaction rate constant to temperature through an activation-energy term. In Reaction Kinetics, the focus is on the analysis, design, implementation, interpretation, or evaluation of Arrhenius equation within Chemical Reaction Engineering, particularly where the Reaction Kinetics module establishes its technical context.', 'SSD_COURSE_043_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M1_S4', 'elementary reactions', '4', 'elementary reactions: Individual reaction steps that represent a single molecular event and whose rate law follows directly from the step''s molecularity. In Reaction Kinetics, the focus is on the analysis, design, implementation, interpretation, or evaluation of elementary reactions within Chemical Reaction Engineering, particularly where the Reaction Kinetics module establishes its technical context.', 'SSD_COURSE_043_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M1_S5', 'kinetic parameter estimation', '5', 'kinetic parameter estimation: Estimating reaction-rate parameters such as rate constants and activation energies from experimental data. In Reaction Kinetics, the focus is on the analysis, design, implementation, interpretation, or evaluation of kinetic parameter estimation within Chemical Reaction Engineering, particularly where the Reaction Kinetics module establishes its technical context.', 'SSD_COURSE_043_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M2_S1', 'batch reactors', '1', 'batch reactors: Reactors in which reactants are charged, allowed to react, and removed without continuous feed during the reaction period. In Ideal Reactors, the focus is on the analysis, design, implementation, interpretation, or evaluation of batch reactors within Chemical Reaction Engineering, particularly where the Ideal Reactors module establishes its technical context.', 'SSD_COURSE_043_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M2_S2', 'Continuous Stirred-Tank Reactor (CSTR)', '2', 'Continuous Stirred-Tank Reactor (CSTR) refers to a continuous stirred-tank reactor assumed to be perfectly mixed so the outlet composition equals the reactor composition. In Ideal Reactors, the focus is on the analysis, design, implementation, interpretation, or evaluation of CSTR within Chemical Reaction Engineering, particularly where the Ideal Reactors module establishes its technical context.', 'SSD_COURSE_043_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M2_S3', 'Plug Flow Reactor (PFR)', '3', 'Plug Flow Reactor (PFR) refers to a plug-flow reactor model in which fluid moves through the reactor with negligible axial mixing. In Ideal Reactors, the focus is on the analysis, design, implementation, interpretation, or evaluation of PFR within Chemical Reaction Engineering, particularly where the Ideal Reactors module establishes its technical context.', 'SSD_COURSE_043_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M2_S4', 'reactor design equations', '4', 'reactor design equations: Equations relating material balances, kinetics, flow, conversion, and reactor volume or residence time for sizing and analysing chemical reactors. In Ideal Reactors, the focus is on the analysis, design, implementation, interpretation, or evaluation of reactor design equations within Chemical Reaction Engineering, particularly where the Ideal Reactors module establishes its technical context.', 'SSD_COURSE_043_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M2_S5', 'residence time', '5', 'residence time refers to the time material spends in a reactor or process region, with its precise definition depending on the flow model. In Ideal Reactors, the focus is on the analysis, design, implementation, interpretation, or evaluation of residence time within Chemical Reaction Engineering, particularly where the Ideal Reactors module establishes its technical context.', 'SSD_COURSE_043_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M3_S1', 'parallel reactions', '1', 'parallel reactions refers to a reaction network in which the same reactant participates in two or more competing reaction pathways. In Multiple Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of parallel reactions within Chemical Reaction Engineering, particularly where the Multiple Reactions module establishes its technical context.', 'SSD_COURSE_043_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M3_S2', 'series reactions', '2', 'series reactions refers to a reaction sequence in which a product of one reaction becomes a reactant in a subsequent reaction. In Multiple Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of series reactions within Chemical Reaction Engineering, particularly where the Multiple Reactions module establishes its technical context.', 'SSD_COURSE_043_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M3_S3', 'selectivity', '3', 'selectivity refers to the extent to which a reaction or process favours formation of a desired product over competing products. In Multiple Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of selectivity within Chemical Process Calculations, particularly where the Balances with Chemical Reactions module establishes its technical context.', 'SSD_COURSE_043_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M3_S4', 'yield', '4', 'yield: Measure of desired product obtained relative to a specified theoretical, feed, or reactant basis; the exact definition depends on the process and stoichiometric basis. In Multiple Reactions, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_043_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M3_S5', 'reaction networks', '5', 'reaction networks refers to a set of chemically connected reactions and species represented through their stoichiometry and kinetic relationships. In Multiple Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of reaction networks within Chemical Reaction Engineering, particularly where the Multiple Reactions module establishes its technical context.', 'SSD_COURSE_043_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M4_S1', 'energy balances', '1', 'energy balances: energy balances in Chemical Reaction Engineering concerns applications of conservation of energy using internal energy, enthalpy, heat transfer, work, and phase or reaction effects as appropriate. In Non-Isothermal Reactor Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of energy balances within Chemical Reaction Engineering, particularly where the Non-Isothermal Reactor Analysis module establishes its technical context.', 'SSD_COURSE_043_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M4_S2', 'heat generation', '2', 'heat generation: Production of heat within a reacting system, commonly from exothermic chemical reactions or other energy-releasing processes. In Non-Isothermal Reactor Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat generation within Chemical Reaction Engineering, particularly where the Non-Isothermal Reactor Analysis module establishes its technical context.', 'SSD_COURSE_043_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M4_S3', 'heat removal', '3', 'heat removal: Transfer of heat out of a reacting system to control temperature and maintain safe or desired operating conditions. In Non-Isothermal Reactor Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat removal within Chemical Reaction Engineering, particularly where the Non-Isothermal Reactor Analysis module establishes its technical context.', 'SSD_COURSE_043_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M4_S4', 'Reactor ignition', '4', 'Reactor ignition: Onset of self-sustained combustion or rapid exothermic reaction in a reactive mixture when thermal and kinetic conditions permit ignition or autoignition. In Non-Isothermal Reactor Analysis, the focus is on curricular scope: Chemical Reaction Engineering; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_043_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M4_S5', 'multiplicity', '5', 'multiplicity refers to the occurrence of multiple possible steady states for the same operating conditions in a nonlinear reactor. In Non-Isothermal Reactor Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of multiplicity within Chemical Reaction Engineering, particularly where the Non-Isothermal Reactor Analysis module establishes its technical context.', 'SSD_COURSE_043_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M5_S1', 'Residence Time Distribution (RTD)', '1', 'RTD: Residence Time Distribution, the distribution of times that fluid elements spend within a reactor. In Residence Time and Reactor Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of RTD within Chemical Reaction Engineering, particularly where the Residence Time and Reactor Performance module establishes its technical context.', 'SSD_COURSE_043_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M5_S2', 'E-curves', '2', 'E-curves: Experimental or normalised RTD representations based on tracer concentration response after a tracer input. In Residence Time and Reactor Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of E-curves within Chemical Reaction Engineering, particularly where the Residence Time and Reactor Performance module establishes its technical context.', 'SSD_COURSE_043_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M5_S3', 'F-curves', '3', 'F-curves: Cumulative residence-time distributions giving the fraction of material that has exited by a specified time. In Residence Time and Reactor Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of F-curves within Chemical Reaction Engineering, particularly where the Residence Time and Reactor Performance module establishes its technical context.', 'SSD_COURSE_043_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M5_S4', 'Phase segregation in reactors', '4', 'Phase segregation in reactors: Separation or non-uniform distribution of phases or species in a reactor, including its effects on transport, reaction rates, residence-time behaviour, and reactor performance. In Residence Time and Reactor Performance, the focus is on curricular scope: Chemical Reaction Engineering; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_043_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M5_S5', 'non-ideal flow', '5', 'non-ideal flow: Reactor flow behaviour that differs from ideal plug-flow or perfectly mixed assumptions. In Residence Time and Reactor Performance, the focus is on the analysis, design, implementation, interpretation, or evaluation of non-ideal flow within Chemical Reaction Engineering, particularly where the Residence Time and Reactor Performance module establishes its technical context.', 'SSD_COURSE_043_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M6_S1', 'gas-solid reactions', '1', 'gas-solid reactions: Heterogeneous reactions involving gaseous reactants or products and a solid phase, with reaction behaviour affected by mass transfer and surface processes. In Heterogeneous Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of gas-solid reactions within Chemical Reaction Engineering, particularly where the Heterogeneous Reactions module establishes its technical context.', 'SSD_COURSE_043_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M6_S2', 'fluid-solid systems', '2', 'fluid-solid systems: Systems in which fluids and solid particles interact through momentum, heat, and mass transfer, including packed, fluidized, or suspended systems. In Heterogeneous Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of fluid-solid systems within Chemical Reaction Engineering, particularly where the Heterogeneous Reactions module establishes its technical context.', 'SSD_COURSE_043_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M6_S3', 'catalyst pellets', '3', 'catalyst pellets: Porous solid catalyst particles used to provide active surface area for heterogeneous reactions. In Heterogeneous Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of catalyst pellets within Chemical Reaction Engineering, particularly where the Heterogeneous Reactions module establishes its technical context.', 'SSD_COURSE_043_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M6_S4', 'effectiveness factors', '4', 'effectiveness factors: Ratios comparing the actual reaction rate in a porous catalyst particle with the rate without internal transport limitations. In Heterogeneous Reactions, the focus is on the analysis, design, implementation, interpretation, or evaluation of effectiveness factors within Chemical Reaction Engineering, particularly where the Heterogeneous Reactions module establishes its technical context.', 'SSD_COURSE_043_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M7_S1', 'reactor selection', '1', 'reactor selection refers to the process of choosing among alternatives for reactor selection using defined performance, service, design, and constraint criteria. In Reactor Design and Scale-Up, the focus is on the analysis, design, implementation, interpretation, or evaluation of reactor selection within Chemical Reaction Engineering, particularly where the Reactor Design and Scale-Up module establishes its technical context.', 'SSD_COURSE_043_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M7_S2', 'Reactor mixing', '2', 'Reactor mixing: Mixing of reactants and fluid phases within a chemical reactor to reduce concentration and temperature gradients and influence transport, reaction rate, selectivity, and residence-time behaviour. In Reactor Design and Scale-Up, the focus is on curricular scope: Chemical Reaction Engineering; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_043_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M7_S3', 'heat transfer', '3', 'heat transfer: Transfer of thermal energy between regions or phases because of a temperature difference, through conduction, convection, radiation, or combinations of these modes. In Reactor Design and Scale-Up, the focus is on the analysis, design, implementation, interpretation, or evaluation of heat transfer within Chemical Reaction Engineering, particularly where the Reactor Design and Scale-Up module establishes its technical context.', 'SSD_COURSE_043_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M7_S4', 'safety', '4', 'safety: Protection of people, assets, systems, and the environment from unacceptable risk arising from hazards through prevention, control, mitigation, and protective measures. In Reactor Design and Scale-Up, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_043_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_043_M7_S5', 'scale-up constraints', '5', 'scale-up constraints: Hydrodynamic, heat-transfer, mass-transfer, safety, and kinetic limits that must be considered when increasing reactor size. In Reactor Design and Scale-Up, the focus is on the analysis, design, implementation, interpretation, or evaluation of scale-up constraints within Chemical Reaction Engineering, particularly where the Reactor Design and Scale-Up module establishes its technical context.', 'SSD_COURSE_043_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M1_S1', 'temperature', '1', 'temperature: Thermodynamic state variable indicating the thermal condition of a system and determining the direction of heat transfer under specified conditions. In Process Measurement, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_044_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M1_S2', 'pressure', '2', 'pressure: Normal force per unit area acting on a surface or within a fluid; in continuum fluid mechanics it is a scalar state variable whose spatial gradients can drive flow. In Process Measurement, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_044_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M1_S3', 'flow', '3', 'flow refers to the rate at which a fluid moves through a process line or equipment. In Process Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of flow within Process Control and Instrumentation, particularly where the Process Measurement module establishes its technical context.', 'SSD_COURSE_044_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M1_S4', 'level', '4', 'level refers to the height or quantity of material contained in a process vessel or tank. In Process Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of level within Process Control and Instrumentation, particularly where the Process Measurement module establishes its technical context.', 'SSD_COURSE_044_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M1_S5', 'analytical measurements', '5', 'analytical measurements refers to the methods and principles used to obtain and interpret measurements of analytical measurements under specified conditions. In Process Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of analytical measurements within Process Control and Instrumentation, particularly where the Process Measurement module establishes its technical context.', 'SSD_COURSE_044_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_044_M1_S6', 'sensor dynamics', '6', 'sensor dynamics refers to the time-dependent response of a sensor to changes in its measured variable. In Process Measurement, the focus is on the analysis, design, implementation, interpretation, or evaluation of sensor dynamics within Process Control and Instrumentation, particularly where the Process Measurement module establishes its technical context.', 'SSD_COURSE_044_M1_S6', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;